async function verifyConnectivity(): Promise<void> {
  const keyRes = await fetch('https://openrouter.ai/api/v1/key', {
    headers: { Authorization: `Bearer ${OPENROUTER_API_KEY}` },
  });
  if (!keyRes.ok) throw new Error(`OpenRouter auth check failed: ${keyRes.status}`);
  const keyData = await keyRes.json();
  const limit = keyData?.data?.limit;
  const usage = keyData?.data?.usage;
  console.log(`[bakeoff] OpenRouter auth OK (usage=${typeof usage === 'number' ? usage : 'n/a'}, limit=${limit === null ? 'unlimited' : (limit ?? 'n/a')})`);
  const modelsRes = await fetch('https://openrouter.ai/api/v1/models');
  if (!modelsRes.ok) throw new Error(`OpenRouter model catalog fetch failed: ${modelsRes.status}`);
  const catalog = await modelsRes.json();
  const ids = new Set<string>((catalog?.data ?? []).map((m: { id: string }) => m.id));
  for (const m of [`${CANDIDATE_MODELS[0]}`, `${CANDIDATE_MODELS[1]}`, 'anthropic/claude-haiku-4.5']) {
    console.log(`[bakeoff] model ${m}: ${ids.has(m) ? 'in catalog' : 'NOT in catalog (will 404 at generation)'}`);
  }
  const probe = await dbQuery('select 1 as ok');
  console.log(`[bakeoff] Supabase DB OK (project ${PROJECT_REF}, probe=${JSON.stringify(probe)})`);
}

async function main(): Promise<void> {
  console.log(`[bakeoff] mode=${DRY_RUN ? 'DRY-RUN (connectivity only, zero generation cost)' : 'LIVE'} dims=${DIMS.join(',')} days=${DAYS} limit=${LIMIT} judge=${USE_JUDGE}`);
  await verifyConnectivity();
  if (DRY_RUN) {
    const rows = await loadBenchmarkRows();
    console.log(`[bakeoff] DRY-RUN: ${rows.length} eligible benchmark rows found:`);
    for (const r of rows) {
      console.log(`  - ${r.video_id} | ${r.created_at.slice(0, 10)} | model_used="${r.model_used}" | digest_model="${r.executive_digest?.model ?? 'n/a'}" | md=${r.analysis_markdown.length}ch | transcript=${r.transcript.length}ch | ${r.title}`);
    }
    console.log('[bakeoff] DRY-RUN complete. No generation performed. Re-run without --dry-run to execute.');
    return;
  }

  const rows = await loadBenchmarkRows();
  const report: Array<DimComparison> = [];
  for (const row of rows) {
    for (const dim of DIMS) {
      const entry: DimComparison = {
        rowId: row.id, videoId: row.video_id, title: row.title, createdAt: row.created_at,
        dimension: dim, benchmarkModel: dim === 0 ? (row.executive_digest?.model ?? 'unknown') : row.model_used,
        benchmarkChars: dim === 0 ? JSON.stringify(row.executive_digest ?? {}).length : (row.analysis_payload?.dimensions?.find((d) => d.number === dim)?.content?.length ?? 0),
        candidates: [],
      };

      let referenceText: string;
      let systemPrompt: string;
      let userPrompt: string;
      let maxTokens: number;
      if (dim === 0) {
        if (!row.executive_digest) {
          console.warn(`[bakeoff] skip ${row.video_id} dim0: no stored executive_digest`);
          continue;
        }
        referenceText = JSON.stringify(row.executive_digest);
        systemPrompt = EXECUTIVE_DIGEST_SYSTEM_FALLBACK;
        userPrompt = buildExecutiveDigestUserMessage(row.analysis_markdown);
        maxTokens = DIGEST_MAX_TOKENS;
      } else {
        const refDim = row.analysis_payload?.dimensions?.find((d) => d.number === dim);
        if (!refDim?.content || !row.transcript) {
          console.warn(`[bakeoff] skip ${row.video_id} dim${dim}: missing stored dimension content or transcript`);
          continue;
        }
        referenceText = refDim.content;
        systemPrompt = '';
        userPrompt = buildDimensionPrompt(dim, row.transcript, row.title);
        maxTokens = DIM_MAX_TOKENS;
      }
      entry.benchmarkChars = referenceText.length;

      for (const model of CANDIDATE_MODELS) {
        try {
          const result = await generate(model, systemPrompt, userPrompt, maxTokens);
          let candidateText = result.text;
          if (dim === 0) {
            const parsed = extractDigestTiers(result.text);
            candidateText = parsed ? JSON.stringify(parsed) : result.text;
          } else {
            const m = result.text.match(/\{[\s\S]*\}/);
            if (m) {
              try {
                const envelope = JSON.parse(m[0]) as { dimensions?: Array<{ number: number; content: string }> };
                const c = envelope.dimensions?.find((d) => d.number === dim)?.content;
                if (c) candidateText = c;
              } catch { /* keep raw text for metrics */ }
            }
          }
          const refTokens = tokenize(referenceText);
          const candTokens = tokenize(candidateText);
          const j = USE_JUDGE ? await judge(referenceText, candidateText) : null;
          entry.candidates.push({
            model,
            finishReason: result.finishReason,
            chars: candidateText.length,
            lengthRatio: referenceText.length > 0 ? candidateText.length / referenceText.length : 0,
            tokenJaccard: Number(jaccard(refTokens, candTokens).toFixed(4)),
            bigramOverlap: Number(bigramOverlap(refTokens, candTokens).toFixed(4)),
            numericOverlap: Number(numericOverlap(referenceText, candidateText).toFixed(4)),
            headingSim: Number(headingSim(referenceText, candidateText).toFixed(4)),
            subsections: dim === 0 ? { required: 4, presentRef: 4, presentCand: (Object.values(extractDigestTiers(candidateText) ?? {}).filter(Boolean).length) } : subsectionPresence(referenceText, candidateText, dim),
            judgeScore: j?.score ?? null,
            judgeNotes: j?.notes ?? null,
            costUsd: result.usage.costUsd,
            error: null,
          });
        } catch (err) {
          entry.candidates.push({
            model, finishReason: 'error', chars: 0, lengthRatio: 0, tokenJaccard: 0, bigramOverlap: 0,
            numericOverlap: 0, headingSim: 0,
            subsections: { required: 0, presentRef: 0, presentCand: 0 },
            judgeScore: null, judgeNotes: null, costUsd: null,
            error: err instanceof Error ? err.message : String(err),
          });
        }
      }
      report.push(entry);
      console.log(`[bakeoff] ${row.video_id} dim${dim}: ${entry.candidates.map((c) => `${c.model.split('/').pop()} j=${c.tokenJaccard} sub=${c.subsections.presentCand}/${c.subsections.required}${c.judgeScore !== null ? ` judge=${c.judgeScore}` : ''}`).join(' | ')}`);
    }
  }

  fs.mkdirSync(path.dirname(OUT_PATH), { recursive: true });
  fs.writeFileSync(OUT_PATH, JSON.stringify({ generatedAt: new Date().toISOString(), dims: DIMS, days: DAYS, limit: LIMIT, judge: USE_JUDGE, report }, null, 2));
  console.log(`[bakeoff] Report written to ${OUT_PATH}`);

  // Aggregate summary per candidate model
  for (const model of CANDIDATE_MODELS) {
    const all = report.flatMap((e) => e.candidates.filter((c) => c.model === model && !c.error));
    if (all.length === 0) continue;
    const mean = (f: (c: (typeof all)[number]) => number) => all.reduce((s, c) => s + f(c), 0) / all.length;
    console.log(`[bakeoff] SUMMARY ${model}: n=${all.length} tokenJaccard=${mean((c) => c.tokenJaccard).toFixed(3)} bigram=${mean((c) => c.bigramOverlap).toFixed(3)} numeric=${mean((c) => c.numericOverlap).toFixed(3)} heading=${mean((c) => c.headingSim).toFixed(3)} lenRatio=${mean((c) => c.lengthRatio).toFixed(2)}${USE_JUDGE ? ` judge=${mean((c) => c.judgeScore ?? 0).toFixed(1)}` : ''}`);
  }
}

main().catch((err) => {
  console.error(`[bakeoff] FATAL: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(1);
});